WITH flattened_attrs AS (SELECT id, customer_id, coupon_codes, items, ship_to, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, FORALL(items, i -> i.qty <= 5) AS all_small_qty, COALESCE(ship_to.country, 'UNKNOWN') AS country_or_unknown, attributes['device'] AS device, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'SPRING10')) SELECT customer_id, COUNT(*) AS cnt, COUNT(*) AS num_rows, COUNT(*) AS num_rows_2, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM flattened_attrs GROUP BY CUBE (customer_id);
